import os
import anthropic

def summarize_text(text_to_summarize: str) -> str:
    """
    Summarizes a long text using the Anthropic Claude 3 Haiku model.

    This function requires the ANTHROPIC_API_KEY environment variable to be set.

    Args:
        text_to_summarize: The string of text to be summarized.

    Returns:
        A string containing the summary, or an error message.
    """
    if not text_to_summarize:
        return "Error: No text provided for summarization."

    try:
        # The Anthropic client automatically uses the ANTHROPIC_API_KEY env var.
        client = anthropic.Anthropic()

        message = client.messages.create(
            model="claude-3-haiku-20240307",
            max_tokens=512,  # Set a max limit for the summary length
            temperature=0.3, # A lower temperature encourages more factual summaries
            system="You are a helpful assistant that specializes in summarizing long documents into concise, easy-to-understand paragraphs.",
            messages=[
                {
                    "role": "user",
                    "content": f"Please summarize the following text:\n\n---\n\n{text_to_summarize}"
                }
            ]
        )

        # The response is a list of content blocks; we extract the text from the first one.
        if message.content and isinstance(message.content[0], anthropic.types.TextBlock):
            return message.content[0].text.strip()
        else:
            return "Error: Failed to generate a valid summary from the API response."

    except Exception as e:
        return f"An error occurred: {e}"
